function renderCourseResults(){const m=data.modules.find(m=>m.id===moduleId),q=search.toLowerCase();let mods=m?[m]:data.modules;mods=mods.filter(x=>filter==='All'||filter==='Saved'||levelFor(x,data.modules.indexOf(x)).toLowerCase().includes(filter.toLowerCase()));const found=mods.map(x=>({...x,lessons:x.lessons.filter(l=>(filter!=='Saved'||state.bookmarks.includes(l.id))&&(!q||[l.title,l.summary,l.focusGlyphs,l.sections.map(s=>s.body).join(' ')].join(' ').toLowerCase().includes(q)))})).filter(x=>x.lessons.length);$('#course-results').innerHTML=!found.length?'<div class="empty">No lessons match. Try another word or level.</div>':(!m&&!q&&filter!=='Saved')?`<div class="grid2">${found.map(x=>moduleCard(x,data.modules.findIndex(y=>y.id===x.id))).join('')}</div>`:found.map(x=>`<div class="section-title"><h2>${esc(x.title)}</h2><span class="small muted">${x.lessons.length} lessons</span></div>${x.lessons.map(lessonRow).join('')}`).join('');}
