async function recordPractice(result){const image=result.image||null;const id=practiceSessionId||String(Date.now());const old=state.sessions.find(s=>s.id===id);if(!old&&!canAddRecord('session'))throw Error('Session limit reached');const session={id,date:old?.date||Date.now(),minutes:Math.min(180,Math.round(Math.max(1,result.duration||1)/6)/10),template:result.template||selectedTemplate,slant:result.slant===50?50:52,image,metrics:result.metrics||{},note:'',kind:'digital'};if(old)state.sessions[state.sessions.indexOf(old)]=session;else state.sessions.unshift(session);if(await save()){practiceSessionId=id;toast('Practice saved to your progress journal.')}else{if(old)state.sessions[state.sessions.indexOf(session)]=old;else state.sessions=state.sessions.filter(s=>s!==session);throw Error('Could not save practice')};}
